mapper.sql:
SELECT i.sku_id, SUM(i.actual_qty) AS history_qty FROM wms_stock_out_item i INNER JOIN wms_stock_out o ON i.stock_out_id = o.stock_out_id AND o.deleted = 0 AND o.status = 4 WHERE i.deleted = 0 AND o.audit_time >= DATE_SUB(NOW(), INTERVAL #{req.historyDays} DAY)
AND o.warehouse_id = #{req.warehouseId}
GROUP BY i.sku_id

SELECT sku_id, SUM(available_qty) AS available_qty FROM wms_inventory WHERE deleted = 0
AND warehouse_id = #{req.warehouseId}
GROUP BY sku_id

mapper.select:
SELECT MIN(s.sku_id) AS sku_id, MIN(s.sku_code) AS sku_code, COALESCE(MAX(p.spu_name), MIN(s.sku_name)) AS sku_name, MIN(s.spec_text) AS spec_text, CASE WHEN COUNT(DISTINCT s.color) > 1 THEN '多色' ELSE MIN(s.color) END AS color, MAX(s.inner_code) AS inner_code, MAX(s.cost_price) AS default_cost, SUM(h.history_qty) AS history_qty, SUM(IFNULL(inv.available_qty, 0)) AS available_qty FROM wms_goods_sku s INNER JOIN () h ON h.sku_id = s.sku_id LEFT JOIN () inv ON inv.sku_id = s.sku_id LEFT JOIN wms_goods_spu p ON s.spu_id = p.spu_id AND p.deleted = 0 WHERE s.deleted = 0
AND s.category_id = #{req.categoryId}
GROUP BY IFNULL(NULLIF(s.inner_code, ''), CONCAT('__SKU__', s.sku_id))
